export const COURSE: Course = {
  id: 'zh-hsk3-exchanges',
  source: 'zh',
  level: 'hsk3',
  entries: [
  { id: "h3x001", tags: ["exchange", "food"], in: { zh: { text: "你饿了吗？｜饿了，我想吃蛋糕。｜厨房里有一个。", reading: "Nǐ è le ma? | È le, wǒ xiǎng chī dàn gāo. | Chú fáng lǐ yǒu yí gè." }, en: { text: "Are you hungry? | Yes, I want some cake. | There's one in the kitchen." }, es: { text: "¿Tienes hambre? | Sí, quiero pastel. | Hay uno en la cocina." } } },
  { id: "h3x002", tags: ["exchange", "food"], in: { zh: { text: "你吃饱了吗？｜还没有，我还想吃香蕉。", reading: "Nǐ chī bǎo le ma? | Hái méi yǒu, wǒ hái xiǎng chī xiāng jiāo." }, en: { text: "Are you full? | Not yet, I still want a banana." }, es: { text: "¿Ya estás lleno? | Todavía no, aún quiero un plátano." } } },
  { id: "h3x003", tags: ["exchange", "food"], in: { zh: { text: "这个面包很新鲜。｜真的吗？我也想吃一个。", reading: "Zhè ge miàn bāo hěn xīn xiān. | Zhēn de ma? Wǒ yě xiǎng chī yí gè." }, en: { text: "This bread is really fresh. | Really? I want one too." }, es: { text: "Este pan está muy fresco. | ¿De verdad? Yo también quiero uno." } } },
  { id: "h3x004", tags: ["exchange", "food"], in: { zh: { text: "你想喝什么饮料？｜我想喝一点儿甜的。", reading: "Nǐ xiǎng hē shén me yǐn liào? | Wǒ xiǎng hē yì diǎnr tián de." }, en: { text: "What drink would you like? | Something sweet, please." }, es: { text: "¿Qué bebida quieres? | Quiero algo dulce." } } },
  { id: "h3x005", tags: ["exchange", "food"], in: { zh: { text: "这个碗里是什么？｜是面条，你要吃吗？｜要！", reading: "Zhè ge wǎn lǐ shì shén me? | Shì miàn tiáo, nǐ yào chī ma? | Yào!" }, en: { text: "What's in this bowl? | Noodles. Do you want some? | Yes!" }, es: { text: "¿Qué hay en este tazón? | Son fideos, ¿quieres? | ¡Sí!" } } },
  { id: "h3x006", tags: ["exchange", "food"], in: { zh: { text: "冰箱里还有蛋糕吗？｜没有了，被我吃了。", reading: "Bīng xiāng lǐ hái yǒu dàn gāo ma? | Méi yǒu le, bèi wǒ chī le." }, en: { text: "Is there any cake left in the fridge? | No, I ate it." }, es: { text: "¿Todavía hay pastel en el refrigerador? | Ya no, me lo comí yo." } } },
  { id: "h3x007", tags: ["exchange", "food"], in: { zh: { text: "你会用筷子吗？｜会，可是我还不习惯。", reading: "Nǐ huì yòng kuài zi ma? | Huì, kě shì wǒ hái bù xí guàn." }, en: { text: "Can you use chopsticks? | Yes, but I'm not used to it yet." }, es: { text: "¿Sabes usar palillos? | Sí, pero todavía no estoy acostumbrado." } } },
  { id: "h3x008", tags: ["exchange", "food"], in: { zh: { text: "这个菜单我看不懂。｜别着急，我给你讲一下。", reading: "Zhè ge cài dān wǒ kàn bù dǒng. | Bié zháo jí, wǒ gěi nǐ jiǎng yí xià." }, en: { text: "I can't understand this menu. | Don't worry, I'll explain it to you." }, es: { text: "No entiendo este menú. | No te preocupes, te lo explico." } } },
  { id: "h3x009", tags: ["exchange", "food"], in: { zh: { text: "盘子里的鱼你不吃吗？｜不吃，我不饿。你吃吧。", reading: "Pán zi lǐ de yú nǐ bù chī ma? | Bù chī, wǒ bú è. Nǐ chī ba." }, en: { text: "Aren't you going to eat the fish on the plate? | No, I'm not hungry. You have it." }, es: { text: "¿No vas a comer el pescado del plato? | No, no tengo hambre. Cómetelo tú." } } },
  { id: "h3x010", tags: ["exchange", "food"], in: { zh: { text: "你一共买了几个苹果？｜一共五个，都给你。", reading: "Nǐ yí gòng mǎi le jǐ gè píng guǒ? | Yí gòng wǔ gè, dōu gěi nǐ." }, en: { text: "How many apples did you buy in all? | Five altogether, and they're all for you." }, es: { text: "¿Cuántas manzanas compraste en total? | Cinco en total, son todas para ti." } } },
  { id: "h3x011", tags: ["exchange", "food"], in: { zh: { text: "这个瓶子里是什么？｜是饮料，很甜。", reading: "Zhè ge píng zi lǐ shì shén me? | Shì yǐn liào, hěn tián." }, en: { text: "What's in this bottle? | It's a drink, and it's very sweet." }, es: { text: "¿Qué hay en esta botella? | Es una bebida, muy dulce." } } },
  { id: "h3x012", tags: ["exchange", "food"], in: { zh: { text: "你想吃面条还是面包？｜我想吃面包，然后喝牛奶。", reading: "Nǐ xiǎng chī miàn tiáo hái shì miàn bāo? | Wǒ xiǎng chī miàn bāo, rán hòu hē niú nǎi." }, en: { text: "Do you want noodles or bread? | Bread, and then I'll have some milk." }, es: { text: "¿Quieres fideos o pan? | Quiero pan, y luego tomo leche." } } },
  { id: "h3x013", tags: ["exchange", "greet"], in: { zh: { text: "好久不见！｜是啊，你最近好吗？｜我很好，谢谢。", reading: "Hǎo jiǔ bú jiàn! | Shì a, nǐ zuì jìn hǎo ma? | Wǒ hěn hǎo, xiè xie." }, en: { text: "Long time no see! | I know! How have you been lately? | I'm good, thanks." }, es: { text: "¡Cuánto tiempo sin verte! | ¡Sí! ¿Cómo has estado últimamente? | Muy bien, gracias." } } },
  { id: "h3x014", tags: ["exchange", "greet"], in: { zh: { text: "早上好！你今天来得真早。｜我一直起得很早。", reading: "Zǎo shang hǎo! Nǐ jīn tiān lái de zhēn zǎo. | Wǒ yì zhí qǐ de hěn zǎo." }, en: { text: "Good morning! You came so early today. | I always get up early." }, es: { text: "¡Buenos días! Hoy llegaste muy temprano. | Siempre me levanto muy temprano." } } },
  { id: "h3x015", tags: ["exchange", "greet"], in: { zh: { text: "你好，我是你的新邻居。｜欢迎！我们做朋友吧。", reading: "Nǐ hǎo, wǒ shì nǐ de xīn lín jū. | Huān yíng! Wǒ men zuò péng you ba." }, en: { text: "Hello, I'm your new neighbor. | Welcome! Let's be friends." }, es: { text: "Hola, soy tu nuevo vecino. | ¡Bienvenido! Seamos amigos." } } },
  { id: "h3x016", tags: ["exchange", "greet"], in: { zh: { text: "你好！我们是第一次见面吧？｜对，很高兴认识你。", reading: "Nǐ hǎo! Wǒ men shì dì yī cì jiàn miàn ba? | Duì, hěn gāo xìng rèn shi nǐ." }, en: { text: "Hi! This is our first time meeting, right? | Yes, nice to meet you." }, es: { text: "¡Hola! Es la primera vez que nos vemos, ¿verdad? | Sí, mucho gusto en conocerte." } } },
  { id: "h3x017", tags: ["exchange", "greet"], in: { zh: { text: "你好，你是校长吗？｜不是，我是新来的。", reading: "Nǐ hǎo, nǐ shì xiào zhǎng ma? | Bú shì, wǒ shì xīn lái de." }, en: { text: "Hello, are you the principal? | No, I'm new here." }, es: { text: "Hola, ¿eres el director? | No, soy nuevo aquí." } } },
  { id: "h3x018", tags: ["exchange", "greet"], in: { zh: { text: "你去哪儿了？我等了你一会儿。｜对不起，我遇到朋友了。", reading: "Nǐ qù nǎr le? Wǒ děng le nǐ yí huìr. | Duì bu qǐ, wǒ yù dào péng you le." }, en: { text: "Where did you go? I waited for you a while. | Sorry, I ran into a friend." }, es: { text: "¿Adónde fuiste? Te esperé un rato. | Perdón, me encontré con un amigo." } } },
  { id: "h3x019", tags: ["exchange", "greet"], in: { zh: { text: "你的帽子真可爱！｜谢谢，是奶奶给我的。", reading: "Nǐ de mào zi zhēn kě ài! | Xiè xie, shì nǎi nai gěi wǒ de." }, en: { text: "Your hat is so cute! | Thanks, my grandma gave it to me." }, es: { text: "¡Tu sombrero es muy lindo! | Gracias, me lo dio mi abuela." } } },
  { id: "h3x020", tags: ["exchange", "greet"], in: { zh: { text: "再见，我要回家了。｜好，路上小心！", reading: "Zài jiàn, wǒ yào huí jiā le. | Hǎo, lù shang xiǎo xīn!" }, en: { text: "Bye, I'm going home. | Okay, be careful on the way!" }, es: { text: "Adiós, ya me voy a casa. | Bien, ¡ten cuidado en el camino!" } } },
  { id: "h3x021", tags: ["exchange", "weather"], in: { zh: { text: "今天刮风了。｜是啊，我的帽子飞走了！", reading: "Jīn tiān guā fēng le. | Shì a, wǒ de mào zi fēi zǒu le!" }, en: { text: "It's windy today. | Yeah, my hat blew away!" }, es: { text: "Hoy hace viento. | Sí, ¡mi sombrero salió volando!" } } },
  { id: "h3x022", tags: ["exchange", "weather"], in: { zh: { text: "今天太阳很大。｜是啊，我想去树下休息。", reading: "Jīn tiān tài yáng hěn dà. | Shì a, wǒ xiǎng qù shù xià xiū xi." }, en: { text: "The sun is strong today. | Yeah, I want to rest under a tree." }, es: { text: "Hoy hay mucho sol. | Sí, quiero ir a descansar bajo un árbol." } } },
  { id: "h3x023", tags: ["exchange", "weather"], in: { zh: { text: "外面下雨了，你带伞了吗？｜带了，我的伞是蓝的。", reading: "Wài mian xià yǔ le, nǐ dài sǎn le ma? | Dài le, wǒ de sǎn shì lán de." }, en: { text: "It's raining outside, did you bring an umbrella? | I did, mine is blue." }, es: { text: "Está lloviendo afuera, ¿trajiste paraguas? | Sí, mi paraguas es azul." } } },
  { id: "h3x024", tags: ["exchange", "weather"], in: { zh: { text: "现在是什么季节？｜是秋天，天气很舒服。", reading: "Xiàn zài shì shén me jì jié? | Shì qiū tiān, tiān qì hěn shū fu." }, en: { text: "What season is it now? | Autumn, and the weather is nice." }, es: { text: "¿En qué estación estamos ahora? | En otoño, y el clima es agradable." } } },
  { id: "h3x025", tags: ["exchange", "weather"], in: { zh: { text: "今天真热，我想开空调。｜好，我马上去开。", reading: "Jīn tiān zhēn rè, wǒ xiǎng kāi kōng tiáo. | Hǎo, wǒ mǎ shàng qù kāi." }, en: { text: "It's so hot today, I want to turn on the air conditioner. | Okay, I'll go do it right now." }, es: { text: "Hoy hace mucho calor, quiero encender el aire acondicionado. | Bien, voy a encenderlo ahora mismo." } } },
  { id: "h3x026", tags: ["exchange", "weather"], in: { zh: { text: "今天天气怎么样？｜不冷也不热，很舒服。", reading: "Jīn tiān tiān qì zěn me yàng? | Bù lěng yě bú rè, hěn shū fu." }, en: { text: "How's the weather today? | Not cold, not hot, very pleasant." }, es: { text: "¿Cómo está el clima hoy? | Ni frío ni calor, muy agradable." } } },
  { id: "h3x027", tags: ["exchange", "weather"], in: { zh: { text: "你怎么感冒了？｜昨天很冷，我忘了多穿衣服。", reading: "Nǐ zěn me gǎn mào le? | Zuó tiān hěn lěng, wǒ wàng le duō chuān yī fu." }, en: { text: "Why did you catch a cold? | It was cold yesterday and I forgot to wear more clothes." }, es: { text: "¿Cómo te resfriaste? | Ayer hizo frío y olvidé ponerme más ropa." } } },
  { id: "h3x028", tags: ["exchange", "weather"], in: { zh: { text: "明天会下雪吗？｜可能会，冬天快到了。｜太好了，我想玩雪！", reading: "Míng tiān huì xià xuě ma? | Kě néng huì, dōng tiān kuài dào le. | Tài hǎo le, wǒ xiǎng wán xuě!" }, en: { text: "Will it snow tomorrow? | Maybe, winter is almost here. | Great, I want to play in the snow!" }, es: { text: "¿Mañana va a nevar? | Quizás, el invierno ya casi llega. | ¡Qué bien, quiero jugar en la nieve!" } } },
  { id: "h3x029", tags: ["exchange", "sleep"], in: { zh: { text: "你怎么还不睡觉？｜我睡不着，我有点儿害怕。｜别怕，我在这儿。", reading: "Nǐ zěn me hái bú shuì jiào? | Wǒ shuì bù zhe, wǒ yǒu diǎnr hài pà. | Bié pà, wǒ zài zhèr." }, en: { text: "Why aren't you asleep yet? | I can't sleep, I'm a little scared. | Don't be scared, I'm here." }, es: { text: "¿Por qué todavía no duermes? | No puedo dormir, tengo un poco de miedo. | No tengas miedo, yo estoy aquí." } } },
  { id: "h3x030", tags: ["exchange", "sleep"], in: { zh: { text: "你几点睡觉？｜我一般十点睡。｜我也是。", reading: "Nǐ jǐ diǎn shuì jiào? | Wǒ yì bān shí diǎn shuì. | Wǒ yě shì." }, en: { text: "What time do you go to bed? | Usually at ten. | Me too." }, es: { text: "¿A qué hora te duermes? | Normalmente me duermo a las diez. | Yo también." } } },
  { id: "h3x031", tags: ["exchange", "sleep"], in: { zh: { text: "你看起来很累。｜是啊，今天我练习了很久。", reading: "Nǐ kàn qǐ lái hěn lèi. | Shì a, jīn tiān wǒ liàn xí le hěn jiǔ." }, en: { text: "You look tired. | Yeah, I practiced for a long time today." }, es: { text: "Te ves muy cansado. | Sí, hoy practiqué mucho tiempo." } } },
  { id: "h3x032", tags: ["exchange", "sleep"], in: { zh: { text: "月亮出来了，我们睡觉吧。｜好，晚安。", reading: "Yuè liang chū lái le, wǒ men shuì jiào ba. | Hǎo, wǎn ān." }, en: { text: "The moon is out, let's go to sleep. | Okay, good night." }, es: { text: "Salió la luna, vamos a dormir. | Bien, buenas noches." } } },
  { id: "h3x033", tags: ["exchange", "sleep"], in: { zh: { text: "我想睡觉了。｜再玩一会儿，好吗？｜不行，明天还要爬山。", reading: "Wǒ xiǎng shuì jiào le. | Zài wán yí huìr, hǎo ma? | Bù xíng, míng tiān hái yào pá shān." }, en: { text: "I'm sleepy. | Play a little longer, okay? | No, we have to climb the mountain tomorrow." }, es: { text: "Tengo sueño. | ¿Jugamos un ratito más, sí? | No, mañana vamos a subir la montaña." } } },
  { id: "h3x034", tags: ["exchange", "sleep"], in: { zh: { text: "你怎么这么累？｜我昨天做作业做到很晚。", reading: "Nǐ zěn me zhè me lèi? | Wǒ zuó tiān zuò zuò yè zuò dào hěn wǎn." }, en: { text: "Why are you so tired? | I did my homework until very late yesterday." }, es: { text: "¿Por qué estás tan cansado? | Ayer hice la tarea hasta muy tarde." } } },
  { id: "h3x035", tags: ["exchange", "random"], in: { zh: { text: "你在看什么？｜我在看照片，是我小时候的。", reading: "Nǐ zài kàn shén me? | Wǒ zài kàn zhào piàn, shì wǒ xiǎo shí hou de." }, en: { text: "What are you looking at? | A photo from when I was little." }, es: { text: "¿Qué estás mirando? | Estoy mirando una foto de cuando yo era pequeño." } } },
  { id: "h3x036", tags: ["exchange", "random"], in: { zh: { text: "你喜欢音乐吗？｜喜欢，我特别喜欢唱歌。", reading: "Nǐ xǐ huan yīn yuè ma? | Xǐ huan, wǒ tè bié xǐ huan chàng gē." }, en: { text: "Do you like music? | Yes, I especially love singing." }, es: { text: "¿Te gusta la música? | Sí, me gusta muchísimo cantar." } } },
  { id: "h3x037", tags: ["exchange", "random"], in: { zh: { text: "你的脚疼吗？｜有一点儿疼，我想休息。", reading: "Nǐ de jiǎo téng ma? | Yǒu yì diǎnr téng, wǒ xiǎng xiū xi." }, en: { text: "Does your foot hurt? | A little, I want to rest." }, es: { text: "¿Te duele el pie? | Me duele un poco, quiero descansar." } } },
  { id: "h3x038", tags: ["exchange", "random"], in: { zh: { text: "周末你想做什么？｜我想去公园玩。｜好，我也去！", reading: "Zhōu mò nǐ xiǎng zuò shén me? | Wǒ xiǎng qù gōng yuán wán. | Hǎo, wǒ yě qù!" }, en: { text: "What do you want to do this weekend? | I want to go play in the park. | Okay, I'm coming too!" }, es: { text: "¿Qué quieres hacer el fin de semana? | Quiero ir a jugar al parque. | ¡Bien, yo también voy!" } } },
  { id: "h3x039", tags: ["exchange", "random"], in: { zh: { text: "你会游泳吗？｜会一点儿，我在努力学。", reading: "Nǐ huì yóu yǒng ma? | Huì yì diǎnr, wǒ zài nǔ lì xué." }, en: { text: "Can you swim? | A little, I'm working hard to learn." }, es: { text: "¿Sabes nadar? | Un poco, me estoy esforzando por aprender." } } },
  { id: "h3x040", tags: ["exchange", "random"], in: { zh: { text: "你为什么哭了？｜我的球坏了。｜别难过，我们再买一个。", reading: "Nǐ wèi shén me kū le? | Wǒ de qiú huài le. | Bié nán guò, wǒ men zài mǎi yí gè." }, en: { text: "Why are you crying? | My ball is broken. | Don't be sad, we'll buy another one." }, es: { text: "¿Por qué lloras? | Mi pelota se rompió. | No estés triste, vamos a comprar otra." } } },
  { id: "h3x041", tags: ["exchange", "random"], in: { zh: { text: "你看，天上有一只鸟！｜它飞得真高！", reading: "Nǐ kàn, tiān shàng yǒu yì zhī niǎo! | Tā fēi de zhēn gāo!" }, en: { text: "Look, there's a bird in the sky! | It flies so high!" }, es: { text: "¡Mira, hay un pájaro en el cielo! | ¡Vuela muy alto!" } } },
  { id: "h3x042", tags: ["exchange", "random"], in: { zh: { text: "你能帮忙吗？｜当然可以，你要我做什么？", reading: "Nǐ néng bāng máng ma? | Dāng rán kě yǐ, nǐ yào wǒ zuò shén me?" }, en: { text: "Can you help? | Of course, what do you need me to do?" }, es: { text: "¿Puedes ayudarme? | Claro que sí, ¿qué quieres que haga?" } } },
  { id: "h3x043", tags: ["exchange", "random"], in: { zh: { text: "你会说中文吗？｜会一点儿，我在学。｜你说得很清楚！", reading: "Nǐ huì shuō zhōng wén ma? | Huì yì diǎnr, wǒ zài xué. | Nǐ shuō de hěn qīng chǔ!" }, en: { text: "Can you speak Chinese? | A little, I'm learning. | You speak very clearly!" }, es: { text: "¿Hablas chino? | Un poco, estoy aprendiendo. | ¡Hablas muy claro!" } } },
  { id: "h3x044", tags: ["exchange", "random"], in: { zh: { text: "这只熊猫真胖！｜是啊，它每天吃很多东西。", reading: "Zhè zhī xióng māo zhēn pàng! | Shì a, tā měi tiān chī hěn duō dōng xi." }, en: { text: "This panda is so chubby! | Yeah, it eats a lot every day." }, es: { text: "¡Este panda está muy gordito! | Sí, todos los días come muchas cosas." } } },
  { id: "h3x045", tags: ["exchange", "random"], in: { zh: { text: "你的照相机在哪儿？｜在我的包里。｜借我用一下，好吗？", reading: "Nǐ de zhào xiàng jī zài nǎr? | Zài wǒ de bāo lǐ. | Jiè wǒ yòng yí xià, hǎo ma?" }, en: { text: "Where's your camera? | In my bag. | Can I borrow it for a bit?" }, es: { text: "¿Dónde está tu cámara? | En mi bolsa. | Préstamela un momento, ¿sí?" } } },
  { id: "h3x046", tags: ["exchange", "random"], in: { zh: { text: "我可以借你的书吗？｜可以，你要记得还我。｜一定！", reading: "Wǒ kě yǐ jiè nǐ de shū ma? | Kě yǐ, nǐ yào jì de hái wǒ. | Yí dìng!" }, en: { text: "Can I borrow your book? | Sure, remember to give it back. | I will!" }, es: { text: "¿Puedo pedirte prestado tu libro? | Sí, pero acuérdate de devolvérmelo. | ¡Sin duda!" } } },
  { id: "h3x047", tags: ["exchange", "random"], in: { zh: { text: "你今天为什么这么高兴？｜因为我的成绩很好！", reading: "Nǐ jīn tiān wèi shén me zhè me gāo xìng? | Yīn wèi wǒ de chéng jì hěn hǎo!" }, en: { text: "Why are you so happy today? | Because my grades are great!" }, es: { text: "¿Por qué estás tan contento hoy? | ¡Porque mis calificaciones son muy buenas!" } } },
  { id: "h3x049", tags: ["exchange", "random"], in: { zh: { text: "你在玩什么游戏？｜一个新游戏，很难。｜我可以试一下吗？", reading: "Nǐ zài wán shén me yóu xì? | Yí gè xīn yóu xì, hěn nán. | Wǒ kě yǐ shì yí xià ma?" }, en: { text: "What game are you playing? | A new one, it's hard. | Can I try it?" }, es: { text: "¿Qué juego estás jugando? | Un juego nuevo, es difícil. | ¿Puedo probarlo?" } } },
  { id: "h3x050", tags: ["exchange", "random"], in: { zh: { text: "你为什么不说话？｜我在想办法，怎么才能爬上去。", reading: "Nǐ wèi shén me bù shuō huà? | Wǒ zài xiǎng bàn fǎ, zěn me cái néng pá shàng qù." }, en: { text: "Why aren't you talking? | I'm figuring out how to climb up there." }, es: { text: "¿Por qué no hablas? | Estoy pensando cómo puedo subir hasta allá." } } },
  { id: "h3x051", tags: ["exchange", "random"], in: { zh: { text: "你的自行车真漂亮！｜谢谢，我每天都骑它。", reading: "Nǐ de zì xíng chē zhēn piào liang! | Xiè xie, wǒ měi tiān dōu qí tā." }, en: { text: "Your bike is so pretty! | Thanks, I ride it every day." }, es: { text: "¡Tu bicicleta es muy bonita! | Gracias, la monto todos los días." } } },
  { id: "h3x052", tags: ["exchange", "random"], in: { zh: { text: "这本书是关于什么的？｜是关于一只熊猫的故事。", reading: "Zhè běn shū shì guān yú shén me de? | Shì guān yú yì zhī xióng māo de gù shì." }, en: { text: "What is this book about? | It's a story about a panda." }, es: { text: "¿De qué trata este libro? | Es un cuento sobre un panda." } } },
  { id: "h3x053", tags: ["exchange", "random"], in: { zh: { text: "你在写什么？｜我在给爷爷写信。", reading: "Nǐ zài xiě shén me? | Wǒ zài gěi yé ye xiě xìn." }, en: { text: "What are you writing? | I'm writing a letter to my grandpa." }, es: { text: "¿Qué estás escribiendo? | Le estoy escribiendo una carta a mi abuelo." } } },
  { id: "h3x054", tags: ["exchange", "random"], in: { zh: { text: "你的裙子是新的吗？｜不是，是我以前买的。", reading: "Nǐ de qún zi shì xīn de ma? | Bú shì, shì wǒ yǐ qián mǎi de." }, en: { text: "Is your skirt new? | No, I bought it a while ago." }, es: { text: "¿Tu falda es nueva? | No, la compré hace tiempo." } } },
  { id: "h3x055", tags: ["exchange", "random"], in: { zh: { text: "你怎么了？｜我的腿走不动了。", reading: "Nǐ zěn me le? | Wǒ de tuǐ zǒu bú dòng le." }, en: { text: "What's wrong? | My legs can't walk any more." }, es: { text: "¿Qué te pasa? | Mis piernas ya no aguantan más." } } },
  { id: "h3x056", tags: ["exchange", "random"], in: { zh: { text: "你听到声音了吗？｜听到了，是有人在唱歌。", reading: "Nǐ tīng dào shēng yīn le ma? | Tīng dào le, shì yǒu rén zài chàng gē." }, en: { text: "Did you hear that sound? | I did, someone is singing." }, es: { text: "¿Oíste ese sonido? | Sí, alguien está cantando." } } },
  { id: "h3x057", tags: ["exchange", "random"], in: { zh: { text: "你想不想去爬山？｜想是想，可是我有点儿担心。｜别担心，我会照顾你。", reading: "Nǐ xiǎng bu xiǎng qù pá shān? | Xiǎng shì xiǎng, kě shì wǒ yǒu diǎnr dān xīn. | Bié dān xīn, wǒ huì zhào gù nǐ." }, en: { text: "Do you want to go hiking? | I do, but I'm a bit worried. | Don't worry, I'll take care of you." }, es: { text: "¿Quieres ir a hacer senderismo? | Sí quiero, pero estoy un poco preocupado. | No te preocupes, yo te cuidaré." } } },
  { id: "h3x058", tags: ["exchange", "random"], in: { zh: { text: "我突然想起一件事。｜什么事？｜今天是妹妹的生日！", reading: "Wǒ tū rán xiǎng qǐ yí jiàn shì. | Shén me shì? | Jīn tiān shì mèi mei de shēng rì!" }, en: { text: "I suddenly remembered something. | What is it? | Today is my little sister's birthday!" }, es: { text: "De repente me acordé de algo. | ¿De qué? | ¡Hoy es el cumpleaños de mi hermana menor!" } } },
  { id: "h3x059", tags: ["exchange", "random"], in: { zh: { text: "你喜欢哪个季节？｜我喜欢夏天，可以游泳。", reading: "Nǐ xǐ huan nǎ ge jì jié? | Wǒ xǐ huan xià tiān, kě yǐ yóu yǒng." }, en: { text: "Which season do you like? | Summer, because I can swim." }, es: { text: "¿Qué estación te gusta? | Me gusta el verano, porque puedo nadar." } } },
  { id: "h3x060", tags: ["exchange", "random"], in: { zh: { text: "这个问题你明白了吗？｜还没有，你再讲一遍吧。", reading: "Zhè ge wèn tí nǐ míng bái le ma? | Hái méi yǒu, nǐ zài jiǎng yí biàn ba." }, en: { text: "Do you understand this problem? | Not yet, please explain it once more." }, es: { text: "¿Ya entendiste este problema? | Todavía no, explícamelo otra vez." } } },
  ],
}
